From 717833ca72d5ba34a692aa0879819350ff4efd3b Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 18:10:49 +0100
Subject: [PATCH] screencast: show a notification when screen sharing starts

The only sign that an app had started sharing the screen was a tray
icon, which is easy to miss and names the app only in its tooltip. Now
a notification names the app when sharing starts and offers to end it.

BUG: 525038
---
 src/screencast.cpp                  | 13 +++++++++++++
 src/xdg-desktop-portal-kde.notifyrc |  6 ++++++
 2 files changed, 19 insertions(+)

diff --git a/src/screencast.cpp b/src/screencast.cpp
index 124c1db4..5d981142 100644
--- a/src/screencast.cpp
+++ b/src/screencast.cpp
@@ -21,6 +21,7 @@

 #include <KConfigGroup>
 #include <KLocalizedString>
+#include <KNotification>
 #include <KSharedConfig>
 #include <KWayland/Client/plasmawindowmanagement.h>
 #include <KWayland/Client/plasmawindowmodel.h>
@@ -303,6 +304,18 @@ QFuture<QVariantList> continueStartAfterDialog(ScreenCastSession *session,
             if (inhibitionsEnabled()) {
                 new NotificationInhibition(session->appId(), i18nc("Do not disturb mode is enabled because...", "Screen sharing in progress"), session);
             }
+            auto notification = new KNotification(u"screencaststarted"_s, KNotification::CloseOnTimeout);
+            notification->setTitle(i18nc("@title:notification", "Screen Sharing Started"));
+            if (const QString appName = Utils::applicationName(session->appId()); !appName.isEmpty()) {
+                notification->setText(i18nc("@info %1 the app that receives the screencast", "Sharing contents to %1", appName));
+            } else {
+                notification->setText(i18nc("@info", "Sharing contents to an unidentifiable application"));
+            }
+            notification->setIconName(u"media-record"_s);
+            auto endAction = notification->addAction(i18nc("@action:button stops screen/window sharing", "End"));
+            QObject::connect(endAction, &KNotificationAction::activated, session, &Session::close);
+            QObject::connect(session, &Session::closed, notification, &KNotification::close);
+            notification->sendEvent();
             qCDebug(XdgDesktopPortalKdeScreenCast) << "Screencast started successfully";
             return {PortalResponse::Success, results};
         });
diff --git a/src/xdg-desktop-portal-kde.notifyrc b/src/xdg-desktop-portal-kde.notifyrc
index a1244a50..e4392837 100644
--- a/src/xdg-desktop-portal-kde.notifyrc
+++ b/src/xdg-desktop-portal-kde.notifyrc
@@ -212,6 +212,12 @@ Comment[zh_TW]=螢幕錄製時發生錯誤
 Action=Popup
 Urgency=Normal

+[Event/screencaststarted]
+Name=Screen Sharing Started
+Comment=An application has started sharing your screens or windows
+Action=Popup
+Urgency=Critical
+
 [Event/remotedesktopstarted]
 Name=Started Remote Desktop
 Name[ar]=يبدأ سطح المكتب بعيد
